source='''def transform(grid):
    """Fill gaps between same-color markers along rows and columns with 2."""
    h, w = len(grid), len(grid[0])
    marker = next((v for row in grid for v in row if v not in (0, 1)), None)
    # The marker is the non-background color. In ARC examples this is 3/9;
    # for the test, the background is 1 and markers are 0.
    if marker is None:
        # Infer the background as the most frequent value, then use other values.
        from collections import Counter
        bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
        marks = {v for row in grid for v in row if v != bg}
    else:
        bg = next((v for row in grid for v in row if v == 0), 0)
        marks = {marker}
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        inds = [c for c, v in enumerate(row) if v in marks]
        if len(inds) >= 2:
            for c in range(min(inds), max(inds)+1):
                if out[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        inds = [r for r in range(h) if grid[r][c] in marks]
        if len(inds) >= 2:
            for r in range(min(inds), max(inds)+1):
                if out[r][c] == bg:
                    out[r][c] = 2
    return out
'''
